package com.vandorlabs.programmer;

import com.vandorlabs.items.ModItems;
import io.netty.buffer.*;
import net.minecraft.block.Block;
import net.minecraft.item.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.WorldServer;

/** The separate Copy operation replaces one existing material item using committed Input data. */
public final class ProgrammerCopyChecks {
    private static int checks;
    private static void require(boolean test,String reason){checks++;if(!test)throw new IllegalStateException("Programmer Copy: "+reason);}
    private static ProgrammerMessage decoded(ProgrammerMessage source){ByteBuf buffer=Unpooled.buffer();try{source.toBytes(buffer);ProgrammerMessage result=new ProgrammerMessage();result.fromBytes(buffer);require(result.decodedValid(),"bounded operation packet roundtrip");return result;}finally{buffer.release();}}
    public static void run(WorldServer world,BlockPos root){
        checks=0;Block block=Block.getBlockFromName("vandorlabs:data_chip_programmer");net.minecraftforge.common.util.FakePlayer actor=net.minecraftforge.common.util.FakePlayerFactory.getMinecraft(world);net.minecraft.inventory.Container previous=actor.openContainer;double x=actor.posX,y=actor.posY,z=actor.posZ;boolean creative=actor.capabilities.isCreativeMode;
        try{actor.capabilities.isCreativeMode=true;actor.setPosition(root.getX()+.5,root.getY()+1,root.getZ()-2);for(int part=0;part<4;part++)world.setBlockState(ProgrammerBlock.cell(root,EnumFacing.NORTH,part),block.getDefaultState().withProperty(ProgrammerBlock.FACING,EnumFacing.NORTH).withProperty(ProgrammerBlock.PART,part),2);ProgrammerTile tile=ProgrammerBlock.at(world,root);ProgrammerContainer container=new ProgrammerContainer(actor.inventory,tile);container.windowId=198;actor.openContainer=container;
            for(Item kind:new Item[]{ModItems.ACCESS_CARD,ModItems.DATA_CHIP})for(int sourceCompany=0;sourceCompany<=6;sourceCompany++)for(int targetCompany=0;targetCompany<=6;targetCompany++){
                tile.clear();ItemStack source=new ItemStack(kind,1,sourceCompany);source.setStackDisplayName("Source "+sourceCompany);NBTTagCompound data=source.getTagCompound();data.setIntArray("PreservedData",new int[]{7,19,sourceCompany});NBTTagCompound nested=new NBTTagCompound();nested.setString("Key","exact source");data.setTag("NestedExample",nested);if(kind==ModItems.DATA_CHIP)ChipJournal.write(source,true,"Saved source Journal",new String[]{"Committed page","Second saved page"});ItemStack target=new ItemStack(kind,1,targetCompany);target.setStackDisplayName("Replace target");ItemStack master=new ItemStack(ModItems.DATA_CHIP,1,6);master.setStackDisplayName("Retained master");tile.setInventorySlotContents(0,master);tile.setInventorySlotContents(1,source);tile.setInventorySlotContents(2,target);
                ItemStack original=source.copy(),masterBefore=master.copy();if(kind==ModItems.DATA_CHIP)tile.configure(true,"Pending draft must not copy",new String[]{"Uncommitted text"});
                require(tile.canCopy()&&!tile.canProgram(),"Copy offered for matching occupied items, Program remains blocked");require(ProgrammerMessage.Handler.apply(actor,decoded(ProgrammerMessage.copy(container.windowId))),"authorized actual Copy packet applied");require(ItemStack.areItemStacksEqual(original,tile.getStackInSlot(2)),"full saved source company/name/NBT/pages replace any target company");require(tile.getStackInSlot(1)==source&&ItemStack.areItemStacksEqual(original,source)&&tile.getStackInSlot(0)==master&&ItemStack.areItemStacksEqual(masterBefore,master),"source and master identity/data unchanged");require(source.getCount()==1&&tile.getStackInSlot(2).getCount()==1&&master.getCount()==1,"one existing item in each slot; no material duplication or extra cost");
                if(kind==ModItems.DATA_CHIP){require(tile.title.equals("Pending draft must not copy")&&ChipJournal.title(tile.getStackInSlot(2)).equals("Saved source Journal"),"Copy neither commits nor discards pending editor draft");tile.removeStackFromSlot(1);require(tile.journalDisplay()!=null&&tile.journalDisplay().source.equals("Output")&&tile.journalDisplay().title.equals("Saved source Journal"),"physical Output Journal displays exact copied committed contents after Input removal");}
            }
            tile.clear();tile.setInventorySlotContents(1,new ItemStack(ModItems.DATA_CHIP,1,2));tile.setInventorySlotContents(2,new ItemStack(ModItems.DATA_CHIP,1,5));require(ProgrammerMessage.Handler.apply(actor,decoded(ProgrammerMessage.copy(198)))&&tile.getStackInSlot(0).isEmpty()&&tile.getStackInSlot(2).getMetadata()==2,"Copy of saved branded data needs no Master");
            tile.clear();tile.setInventorySlotContents(1,new ItemStack(ModItems.ACCESS_CARD,1,2));tile.setInventorySlotContents(2,new ItemStack(ModItems.DATA_CHIP,1,3));ItemStack target=tile.getStackInSlot(2).copy();require(!tile.canCopy()&&!ProgrammerMessage.Handler.apply(actor,decoded(ProgrammerMessage.copy(198)))&&ItemStack.areItemStacksEqual(target,tile.getStackInSlot(2)),"different base kinds rejected without mutation");
            tile.removeStackFromSlot(2);require(!tile.canCopy(),"empty Output disables Copy");tile.setInventorySlotContents(2,new ItemStack(ModItems.ACCESS_CARD,1,5));tile.removeStackFromSlot(1);require(!tile.canCopy(),"empty Input disables Copy");tile.setInventorySlotContents(1,new ItemStack(ModItems.ACCESS_CARD,1,2));tile.getStackInSlot(1).setCount(2);require(!tile.canCopy(),"malformed multiple source items rejected");tile.getStackInSlot(1).setCount(1);tile.getStackInSlot(2).setCount(2);require(!tile.canCopy(),"malformed multiple target items rejected");tile.getStackInSlot(2).setCount(1);
            target=tile.getStackInSlot(2).copy();require(!ProgrammerMessage.Handler.apply(actor,decoded(ProgrammerMessage.copy(199)))&&ItemStack.areItemStacksEqual(target,tile.getStackInSlot(2)),"wrong window cannot overwrite Output");actor.setPosition(root.getX()+30,root.getY(),root.getZ());require(!ProgrammerMessage.Handler.apply(actor,decoded(ProgrammerMessage.copy(198))),"out-of-reach Copy rejected");actor.setPosition(root.getX()+.5,root.getY()+1,root.getZ()-2);actor.openContainer=previous;require(!ProgrammerMessage.Handler.apply(actor,decoded(ProgrammerMessage.copy(198))),"unrelated container cannot copy");actor.openContainer=container;
            ByteBuf wire=Unpooled.buffer();try{ProgrammerMessage.copy(198).toBytes(wire);require(wire.getUnsignedByte(4)==ProgrammerMessage.COPY&&wire.readableBytes()==24,"Copy appended operation2 has bounded empty draft payload");wire.setByte(4,3);ProgrammerMessage invalid=new ProgrammerMessage();invalid.fromBytes(wire);require(!invalid.decodedValid()&&!ProgrammerMessage.Handler.apply(actor,invalid),"unknown operation rejected before mutation");}finally{wire.release();}
            for(boolean program:new boolean[]{false,true}){wire=Unpooled.buffer();try{new ProgrammerMessage(198,program,false,"",new String[0]).toBytes(wire);require(wire.getUnsignedByte(4)==(program?1:0),"legacy Draft0 and Program1 operation bytes preserved");}finally{wire.release();}}
        }finally{actor.openContainer=previous;actor.capabilities.isCreativeMode=creative;actor.setPosition(x,y,z);for(int part=0;part<4;part++)world.removeTileEntity(ProgrammerBlock.cell(root,EnumFacing.NORTH,part));for(int part=3;part>=0;part--)world.setBlockToAir(ProgrammerBlock.cell(root,EnumFacing.NORTH,part));}
        System.out.println("[vandorlabs][reprolab] programmer-copy PASS checks="+checks+" actual bounded packet/container 98 cross-company card/chip pairs exact savedInputNBT immutableInputMaster reusedOutput material draft-isolation worldJournal malformed/wrongwindow/reach guards legacy0/1 opcodes");
    }
    private ProgrammerCopyChecks(){}
}
